\entrytitle{30}{Binary integer programming with few inequalities}{strengthPolynomial}{evidencePartial}{hardwareExponential}
\setcounter{problem}{29}
\begin{problem}[Binary integer programming]
Given $A\in\mathbb Z^{d\times n}$ and $b\in\mathbb Z^d$, find $x\in\{0,1\}^n$ satisfying $Ax\leq b$, or decide infeasibility. An additional profit threshold converts a linear optimization problem into this form. The regime of interest has fixed or slowly growing $d$ and binary-encoded coefficients.
The few-inequality quantum bound uses coherent-memory time with bit-arithmetic costs, classical meet in the middle uses RAM time, and bounded-row-arity encodings use bit complexity.
\end{problem}
\speedupheading
\complexity{Quantum}{$\widetilde O(2^{n/3}n^d)$, Arvind--Schuler integer-programming algorithm.}
The polynomial arithmetic factors depend on coefficient bit length. For $d=o(n/\log n)$, the time is $2^{(1/3+o(1))n}$. Precomputed partial-sum vectors support coherent multidimensional range queries; both preprocessing and searching are included in the bound. With $B$-bit coefficients, direct arithmetic and comparisons have reversible cost polynomial in $dn(B+\log n)$.
\complexity{Classical}{$O^*(2^{n/2})$ for fixed $d$, meet in the middle with dominance searching.}
The two lists of partial-sum vectors are combined by coordinatewise inequalities and use exponential memory. For a different regime in which every row has support at most a fixed $r$, encode each forbidden local assignment as a clause using the original $n$ Boolean variables. Polynomially many rows then give $\operatorname{poly}(\text{input size})2^{O_r(n\log\log n/\sqrt{\log n})}$ deterministic time and polynomial space; linearly many rows improve the exponent to $O_r(n/\sqrt{\log n})$. A fixed number of dense, large-coefficient inequalities retains the few-constraint meet-in-the-middle comparison.
\dimensionlabel{Strength}{strengthPolynomial} Polynomial speedup through a smaller exponential constant for fixed $d$ and unrestricted row support, using Grover search and amplitude amplification. Bounded-row-arity instances have the stronger subexponential classical comparator.
\dimensionlabel{Evidence}{evidencePartial} Rigorous quantum upper bounds in the specified access model, with partial evidence against the best displayed classical algorithms in the few-dense-inequality regime.
\dimensionlabel{Hardware}{hardwareExponential} The active assignment register has $n$ qubits; $d$ arithmetic accumulators require input-dependent bit width. Exponential coherent range-search data and long searches dominate large-instance implementation. Increasing $d$ raises both the $n^d$ factor and arithmetic cost.
\subhead{Algorithm}
\begin{algorithmindex}{30}
\item \href{https://arxiv.org/pdf/quant-ph/0212048}{Arvind and Schuler, \emph{The Quantum Query Complexity of 0-1 Knapsack and Associated Claw Problems} (ISAAC 2003)}. Section 2, Theorem 1 and steps 1--6, pp.~3--4: partial-sum preprocessing, range-tree queries and quantum search; Corollary 2 gives threshold optimization.
\item \href{https://github.com/openai/math/blob/main/preprints/The-Exponential-Time-Hypothesis-is-False-October-25-2026/paper.pdf}{OpenAI, \emph{The Exponential Time Hypothesis Is False} (2026)}. Theorem 1.1 and Appendices D.1--D.4, applied to the bounded-row-arity clauses.
\end{algorithmindex}
